const norm = (v) => (v === undefined || v === null) ? '' : String(v).trim();
const digits = (v) => norm(v).replace(/\D/g, '');
const yes = (v) => ['yes', 'true', '1', 'y'].includes(norm(v).toLowerCase());
const hoursSince = (iso) => { const t = Date.parse(norm(iso)); return Number.isNaN(t) ? Infinity : (Date.now() - t) / 3600000; };
const daysSince = (iso) => hoursSince(iso) / 24;
const nowIso = () => new Date().toISOString();
const appLink = () => norm($env.APP_DOWNLOAD_LINK);
const vendorLink = () => norm($env.APP_VENDOR_LINK) || appLink();
const flag = (v) => ['true', 'yes', '1'].includes(norm(v).toLowerCase());
const stopped = () => flag($env.AUTOPILOT_STOP);
const autopilotOn = () => flag($env.AUTOPILOT_SOCIAL_POSTING);
const bufferProfile = (platform) => norm($env['BUFFER_PROFILE_ID_' + String(platform).toUpperCase()]);
return [{ json: { emergency_stop: stopped() } }];

const norm = (v) => (v === undefined || v === null) ? '' : String(v).trim();
const digits = (v) => norm(v).replace(/\D/g, '');
const yes = (v) => ['yes', 'true', '1', 'y'].includes(norm(v).toLowerCase());
const hoursSince = (iso) => { const t = Date.parse(norm(iso)); return Number.isNaN(t) ? Infinity : (Date.now() - t) / 3600000; };
const daysSince = (iso) => hoursSince(iso) / 24;
const nowIso = () => new Date().toISOString();
const appLink = () => norm($env.APP_DOWNLOAD_LINK);
const vendorLink = () => norm($env.APP_VENDOR_LINK) || appLink();
const flag = (v) => ['true', 'yes', '1'].includes(norm(v).toLowerCase());
const stopped = () => flag($env.AUTOPILOT_STOP);
const autopilotOn = () => flag($env.AUTOPILOT_SOCIAL_POSTING);
const bufferProfile = (platform) => norm($env['BUFFER_PROFILE_ID_' + String(platform).toUpperCase()]);
const tpls = ['WELCOME_D1', 'WELCOME_D2', 'WELCOME_D3', 'REENGAGE_7', 'REENGAGE_14', 'REENGAGE_21', 'NURTURE_VENDOR_D1', 'NURTURE_VENDOR_D2', 'NURTURE_VENDOR_D3', 'NURTURE_VENDOR_D7', 'NURTURE_VENDOR_D14', 'NURTURE_BUYER_D1', 'NURTURE_BUYER_D3', 'NURTURE_BUYER_D5', 'WAITLIST_CONFIRM'];
const missing = tpls.filter((k) => !norm($env['WA_TPL_' + k]));
return [{ json: {
  today: nowIso().slice(0, 10),
  autopilot_social: autopilotOn(),
  ai_configured: !!norm($env.AI_API_KEY),
  whatsapp_configured: !!norm($env.WHATSAPP_ACCESS_TOKEN) && !!norm($env.WHATSAPP_PHONE_NUMBER_ID),
  whatsapp_templates_missing: missing,
  buffer_configured: !!norm($env.BUFFER_API_KEY),
  email_configured: !!norm($env.RESEND_API_KEY) && !!norm($env.RESEND_FROM_EMAIL),
} }];

const norm = (v) => (v === undefined || v === null) ? '' : String(v).trim();
const digits = (v) => norm(v).replace(/\D/g, '');
const yes = (v) => ['yes', 'true', '1', 'y'].includes(norm(v).toLowerCase());
const hoursSince = (iso) => { const t = Date.parse(norm(iso)); return Number.isNaN(t) ? Infinity : (Date.now() - t) / 3600000; };
const daysSince = (iso) => hoursSince(iso) / 24;
const nowIso = () => new Date().toISOString();
const appLink = () => norm($env.APP_DOWNLOAD_LINK);
const vendorLink = () => norm($env.APP_VENDOR_LINK) || appLink();
const cfg = $('Gather Config Health').first().json;
const rows = (n) => $(n).all().map((i) => i.json).filter((r) => Object.values(r).some((v) => norm(v) !== ''));
const posts = rows('Read Social Posts'); const leads = rows('Read Leads'); const convos = rows('Read WhatsApp Conversations');
const today = cfg.today;
const todayPosts = posts.filter((p) => norm(p.date) === today);
const st = (l) => norm(l.status).toLowerCase();
const s = {
  date: today,
  leads_captured_today: leads.filter((l) => norm(l.first_contact).startsWith(today)).length,
  total_leads: leads.length,
  opted_in: leads.filter((l) => yes(l.opt_in) && !norm(l.opt_out_at)).length,
  unsubscribed: leads.filter((l) => st(l) === 'unsubscribed' || norm(l.opt_out_at)).length,
  posts_generated: todayPosts.length, posts_approved: todayPosts.filter((p) => norm(p.status) === 'approved').length, posts_flagged: todayPosts.filter((p) => norm(p.status) === 'flagged').length,
  conversations_today: convos.filter((c) => norm(c.timestamp).startsWith(today)).length,
};
const lines = [
  'Eki Autopilot Daily Report - ' + s.date, '',
  'Leads: +' + s.leads_captured_today + ' today, ' + s.total_leads + ' total, ' + s.opted_in + ' opted-in, ' + s.unsubscribed + ' unsubscribed',
  'Social posts (today): ' + s.posts_generated + ' generated, ' + s.posts_approved + ' approved, ' + s.posts_flagged + ' flagged',
  'WhatsApp conversations today: ' + s.conversations_today, '',
  'Config health:',
  '- Social auto-posting: ' + (cfg.autopilot_social ? 'ON' : 'OFF (manual)'),
  '- AI provider key: ' + (cfg.ai_configured ? 'set' : 'MISSING'),
  '- WhatsApp API: ' + (cfg.whatsapp_configured ? 'set' : 'MISSING'),
  '- WhatsApp templates missing: ' + (cfg.whatsapp_templates_missing.length ? cfg.whatsapp_templates_missing.length + ' (' + cfg.whatsapp_templates_missing.join(', ') + ')' : 'none'),
  '- Buffer: ' + (cfg.buffer_configured ? 'set' : 'not set') + ' | Email (Resend): ' + (cfg.email_configured ? 'set' : 'MISSING'),
];
return [{ json: { ...s, text: lines.join('\n') } }];
